using UnityEngine;
using UnityEngine.UIElements;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var ts = Homesteader.UI.TimeSystem.Instance;
        ts.SetSpeed(Homesteader.UI.HomesteaderSpeed.Speed9X);
        ts.Tick(60f);
        var hud = GameObject.Find("HudRoot");
        var doc = hud.GetComponent<UIDocument>();
        var root = doc.rootVisualElement;
        var bindings = hud.GetComponent<Homesteader.UI.HudBindings>();
        if (bindings == null) { result.Log("no bindings"); return; }
        bindings.SendMessage("Update", SendMessageOptions.DontRequireReceiver);
        var cl = root.Q<Label>("ClockLabel");
        var dx = root.Q<Label>("DayLabel");
        var sl = root.Q<Label>("SeasonLabel");
        var rw = root.Q<Label>("ResourceWaterLabel");
        var msg = "Clock=" + (cl != null ? cl.text : "??");
        msg = msg + " Day=" + (dx != null ? dx.text : "??");
        msg = msg + " Season=" + (sl != null ? sl.text : "??");
        msg = msg + " Water=" + (rw != null ? rw.text : "??");
        result.Log(msg);
    }
}
